"use strict";
// buildcmd.cmd.civet

import {LOG, DBG, WARN, ERR} from 'logger'
import {assert, defined, croak} from 'base'
import {EXEC} from 'llutils'
import {cmdStep} from 'cmd-utils'
import {getCmdArgs, inspect} from 'cmd-args'
import {withExt, findFile, isFile} from 'fsys'
import {doInstallCmd} from 'exec'
import {doCompileCivet} from 'civet'
import {procFiles, procOneFile} from 'proc-files'
import {doUnitTest} from 'compile'

const [
	lStubs,
	{force, noInstall, doTest, inspectTest}
	] = getCmdArgs('buildcmd', {
		_:           {range: [1,99]},
		force:       {flag: 'f', desc: 'force recompile'},
		noInstall:   {flag: 'n', desc: 'do not install'},
		doTest:      {flag: 't', desc: 'run unit test if it exists'},
		inspectTest: {flag: 'J', desc: 'inspect unit test'}
		})

// ---------------------------------------------------------------------------

await EXEC(async () => {
	if (lStubs[0] === 'all') {
		LOG(cmdStep("BUILD ALL CMDS"))
		const [hCounts] = await procFiles(
			[doCompileCivet, ['src/**/*.cmd.civet']],
			{force, quiet: true})
		if (hCounts.err > 0) {
			ERR(`${hCounts.err} cmds didn't compile`)
		}
		else {
			if (hCounts.processed > 0) {
				LOG(`${hCounts.processed} cmd files compiled`)
			}
			if (doTest) {
				const [hTestCounts] = await procFiles([doUnitTest, ['src/**/*.cmd.ts']], {
					capture: false
					})
				if (hTestCounts.err > 0) {
					ERR(`${hTestCounts.err} unit tests didn't compile`)
				}
				else if (hTestCounts.processed > 0) {
					LOG(`${hTestCounts.processed} cmd unit tests run`)
				}
			}
		}
		if (!noInstall) {
			const [hInstallCounts] = await procFiles(
				[doInstallCmd, ['src/**/*.cmd.ts']])
			if (hInstallCounts.processed > 0) {
				LOG("#{hInstallCounts.processed] commands installed")
			}
		}
	}
	else {
		for (const stub of lStubs) {
			LOG(cmdStep(`BUILD CMD ${stub}`))

			const fileName = `${stub}.cmd.civet`
			const path = findFile(fileName)
			assert(defined(path), `No such file: ${fileName}`)

			await procOneFile(
				path,
				doCompileCivet,
				{force, inspect})

			const tsPath = withExt(path, '.ts')
			assert(isFile(tsPath), `File ${tsPath} not created`)

			if (doTest) {
				LOG(cmdStep(`RUN TEST FOR ${stub}`))

				const tsPath = withExt(path, '.ts')
				await procOneFile(tsPath, doUnitTest, {
					capture: true,
					inspect: inspectTest
					})
			}

			if (!noInstall) {
				await procOneFile(tsPath, doInstallCmd)
			}
			else {
				LOG("not installed (use -i to install)")
			}
		}
	}
})

